    "html": "<nav class=\"public-nav\" aria-label=\"Public navigation\"><a class=\"public-brand\" href=\"#landing\"><span class=\"brandmark\"><svg viewBox=\"0 0 32 32\" aria-hidden=\"true\" focusable=\"false\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M23 6.5h-7.5C10 6.5 6 10.5 6 16s4 9.5 9.5 9.5H23\" stroke=\"currentColor\" stroke-width=\"3.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"></path><rect x=\"20.2\" y=\"13.2\" width=\"5.6\" height=\"5.6\" rx=\"1.1\" fill=\"currentColor\"></rect></svg></span><span>ChangeProof</span><em>AI</em></a><div class=\"public-links\"><a class=\"nav-product\" href=\"#product\">Product</a><a class=\"nav-price\" href=\"#pricing\">Pricing</a><a class=\"nav-documentation\" href=\"#guides\">Documentation</a><button type=\"button\" class=\"icon-btn theme-toggle\" data-evidence=\"theme\" aria-label=\"Switch to dark mode\" aria-pressed=\"false\" title=\"Switch to dark mode\"><svg class=\"icon theme-moon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13Z\"></path></svg><svg class=\"icon theme-sun\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5\"></path></svg></button><a class=\"public-login\" href=\"#login\">Sign in</a><a class=\"primary cp-get-started-cta\" href=\"#register\">Get started free <svg class=\"icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 12h16m-6-6 6 6-6 6\"></path></svg></a></div></nav><div class=\"public-page\"><div class=\"modern-container\"><div class=\"public-breadcrumb\"><a href=\"#landing\">Home</a><span>/</span><span>Product notes</span></div><header class=\"public-page-hero\"><span class=\"section-eyebrow\">Product notes</span><h1>Follow ChangeProof's progress.</h1><p>Design notes and product direction with clear status.</p></header><div class=\"public-page-content\"><aside class=\"public-note\"><svg class=\"icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 11v6M12 7h.01\"></path></svg><div><strong>Product updates</strong><p>Follow improvements to workflows, integrations, and the ChangeProof experience.</p></div></aside><div class=\"public-release\"><div><span class=\"badge\">Current design</span><p>Public experience</p></div><article><h2>Explore ChangeProof before signing in.</h2><p>Explore product features, pricing, documentation, tutorials, templates, help, and evidence reports.</p><ul><li>Public navigation is separate from the workspace.</li><li>Light and dark themes across the site.</li><li>Read evidence reports before reviewing workspace results.</li><li>Workspace pages require sign-in first.</li></ul></article></div><div class=\"public-release\"><div><span class=\"badge\">Visual foundation</span><p>Evidence design</p></div><article><h2>Every change. One proof.</h2><p>Clear headlines, impact maps, candidate diffs, and decision trails shape the visual experience.</p></article></div></div><section class=\"public-related\"><span class=\"section-eyebrow\">Keep reading</span><div><a href=\"#roadmap\"><span>Roadmap</span><svg class=\"icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 12h16m-6-6 6 6-6 6\"></path></svg></a><a href=\"#guides\"><span>Documentation</span><svg class=\"icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 12h16m-6-6 6 6-6 6\"></path></svg></a></div></section></div></div><footer class=\"modern-footer\"><div class=\"modern-container\"><div class=\"footer-top\"><div class=\"footer-follow\">Follow our journey<br>&amp; product updates.<br><a href=\"#changelog\"><svg class=\"icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 5c-3-3-7-3-10-2v16c3-1 7-1 10 2 3-3 7-3 10-2V3c-3-1-7-1-10 2zm0 0v16\"></path></svg>View product notes <svg class=\"icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 12h16m-6-6 6 6-6 6\"></path></svg></a></div><div class=\"footer-col\"><h3>Product</h3><a href=\"#pricing\">Pricing</a><a href=\"#changelog\">Changelog</a><a href=\"#roadmap\">Support roadmap</a></div><div class=\"footer-col\"><h3>Learn</h3><a href=\"#templates\">Run templates</a><a href=\"#tutorials\">Tutorial</a><a href=\"#sample-report\">Evidence report</a></div><div class=\"footer-col\"><h3>Connect</h3><a href=\"#help\">Help center</a><a href=\"#privacy-policy\">Privacy</a><a href=\"#login\">Sign in</a><a href=\"#register\">Get started free</a></div></div><div class=\"footer-legal\"><span>© 2026 ChangeProof AI</span><a href=\"#landing\" data-evidence-scroll=\"top\">Back to top</a></div></div><div class=\"footer-wordmark\" aria-hidden=\"true\">ChangeProof</div></footer>"
